int is_1122(char *S){
    int n=strlen(S);
    int mid=n/2;
    if(n%2==0) return 0;
    if(S[mid]!='/') return 0;
    for(int i=0;i<mid;i++) if(S[i]!='1') return 0;
    for(int i=mid+1;i<n;i++) if(S[i]!='2') return 0;
    return 1;
}

